"""Small protocol adapters and bounded retries around one model request."""

from __future__ import annotations

import asyncio
import hashlib
import json
import logging
import re
import time
from copy import deepcopy
from itertools import islice
from typing import Any

import httpx

from .config import Settings
from .evidence import Redactor
from .schema import ModelReply, ToolCall


class ContextHistoryError(ValueError):
    pass


def history_groups(history):
    """Validate complete tool exchanges and keep their reasoning in the same cut group."""
    groups, group, pending, seen, returned = [], [], set(), set(), set()
    accepting_calls = False
    for item in history:
        kind, role = item.get("type"), item.get("role")
        calls, outputs = [], []
        if kind == "function_call":
            calls = [item.get("call_id")]
        elif kind == "function_call_output":
            outputs = [item.get("call_id")]
        if item.get("tool_calls"):
            if role != "assistant":
                raise ContextHistoryError("invalid_tool_role: calls require an assistant message")
            calls.extend(call.get("id") for call in item["tool_calls"])
        if role == "tool":
            outputs.append(item.get("tool_call_id"))
        content = item.get("content")
        if isinstance(content, list):
            saw_other_block = False
            for block in content:
                if not isinstance(block, dict):
                    continue
                if block.get("type") == "tool_use":
                    if role != "assistant":
                        raise ContextHistoryError(
                            "invalid_tool_role: tool_use requires an assistant message"
                        )
                    calls.append(block.get("id"))
                elif block.get("type") == "tool_result":
                    if role != "user" or saw_other_block:
                        raise ContextHistoryError(
                            "invalid_tool_order: tool_result must lead a user message"
                        )
                    outputs.append(block.get("tool_use_id"))
                else:
                    saw_other_block = True
        if any(not isinstance(key, str) or not key.strip() for key in calls + outputs):
            raise ContextHistoryError("invalid_tool_id: tool calls and results need nonempty ids")
        if len(calls) != len(set(calls)) or seen.intersection(calls):
            raise ContextHistoryError("duplicate_tool_call: history contains a reused call id")
        if calls and outputs:
            raise ContextHistoryError(
                "invalid_tool_order: calls and results cannot share a message"
            )
        if outputs:
            for key in outputs:
                if key in returned:
                    raise ContextHistoryError("duplicate_tool_output: each call needs one result")
                if key not in pending:
                    raise ContextHistoryError(
                        "orphan_tool_output: history must retain complete exchanges"
                    )
                pending.remove(key)
                returned.add(key)
            if role == "user" and pending:
                raise ContextHistoryError("missing_tool_output: native result batch is incomplete")
            group.append(item)
            accepting_calls = False
            if not pending:
                groups.append(group)
                group = []
            continue
        if pending and not (kind == "function_call" and accepting_calls):
            raise ContextHistoryError("missing_tool_output: next turn starts before results")
        new_turn = kind == "reasoning" or role in {"user", "assistant", "system"}
        if group and not pending and new_turn:
            # Contiguous reasoning belongs to the following assistant response/call batch.
            if role in {"user", "system"} or any(x.get("type") != "reasoning" for x in group):
                groups.append(group)
                group = []
        pending.update(calls)
        seen.update(calls)
        accepting_calls = bool(calls) and kind == "function_call"
        group.append(item)
        if role in {"user", "system"}:
            groups.append(group)
            group = []
    if pending:
        raise ContextHistoryError("missing_tool_output: history ends before results")
    if group:
        groups.append(group)
    return groups


class ProviderError(RuntimeError):
    """Safe diagnostics suitable for the trace; never contains request headers/body."""

    def __init__(
        self,
        message: str,
        *,
        category="provider_error",
        status=None,
        code="",
        attempts=1,
        usage=None,
        diagnostics=None,
    ):
        self.details = {
            "category": category,
            "status": status,
            "code": code,
            "message": message,
            "attempts": attempts,
            "usage": dict(usage or {}),
            "diagnostics": dict(diagnostics or {}),
        }
        super().__init__(json.dumps(self.details, ensure_ascii=False))


_USAGE_FIELDS = {
    "input_tokens",
    "output_tokens",
    "prompt_tokens",
    "completion_tokens",
    "total_tokens",
    "cached_tokens",
    "cache_write_tokens",
    "cache_read_input_tokens",
    "cache_creation_input_tokens",
    "reasoning_tokens",
    "audio_tokens",
    "accepted_prediction_tokens",
    "rejected_prediction_tokens",
    "uncached_tokens",
    "ephemeral_5m_input_tokens",
    "ephemeral_1h_input_tokens",
}


def _numeric_usage(raw):
    """Keep known counters, never arbitrary strings or provider-supplied mapping keys."""

    def counts(value):
        if not isinstance(value, dict):
            return {}
        return {
            key: value[key]
            for key in sorted(_USAGE_FIELDS)
            if type(value.get(key)) is int and 0 <= value[key] <= 2**63 - 1
        }

    result = counts(raw)
    if not isinstance(raw, dict):
        return result
    for key in (
        "input_tokens_details",
        "output_tokens_details",
        "prompt_tokens_details",
        "completion_tokens_details",
        "cache_creation",
    ):
        if isinstance(raw.get(key), dict):
            result[key] = counts(raw[key])
    attribution = raw.get("attribution")
    if isinstance(attribution, dict):
        result["attribution"] = attr = {}
        items = attribution.get("items")
        if isinstance(items, dict):
            attr["items_count"] = len(items)
            # IDs and content are deliberately omitted; top-level item counters suffice.
            attr["items"] = [counts(value) for value in islice(items.values(), 128)]
        fields = attribution.get("request_fields")
        if isinstance(fields, dict):
            attr["request_fields_count"] = len(fields)
            attr["request_fields"] = {
                key: counts(fields[key])
                for key in ("tools", "instructions", "messages", "input", "system")
                if key in fields
            }
    return result


def _usage_warnings(raw, usage):
    flags = []
    for left, right in (("input_tokens", "prompt_tokens"), ("output_tokens", "completion_tokens")):
        if left in raw and right in raw and raw[left] != raw[right]:
            flags.append(left + "_aliases_disagree")
    if all(key in usage for key in ("input_tokens", "output_tokens", "total_tokens")):
        if usage["total_tokens"] != usage["input_tokens"] + usage["output_tokens"]:
            flags.append("total_tokens_disagree")
    for part, total in (
        ("cache_read_input_tokens", "input_tokens"),
        ("reasoning_tokens", "output_tokens"),
    ):
        if part in usage and total in usage and usage[part] > usage[total]:
            flags.append(part + "_exceeds_" + total)
    attr = raw.get("attribution", {})
    items, fields = attr.get("items", []), attr.get("request_fields", {})
    if (
        items
        and len(items) == attr.get("items_count")
        and len(fields) == attr.get("request_fields_count")
        and all("input_tokens" in part for part in [*items, *fields.values()])
        and "input_tokens" in usage
    ):
        total = sum(part["input_tokens"] for part in [*items, *fields.values()])
        if total != usage["input_tokens"]:
            flags.append("input_attribution_disagrees")
    return flags


def _validated_reply(text, calls, raw, data, usage, *, opaque=False):
    if not isinstance(text, str) or not isinstance(data.get("model", ""), str):
        raise ValueError("invalid response text/model")
    ids = [call.call_id for call in calls]
    if len(ids) != len(set(ids)) or any(not key.strip() for key in ids):
        raise ValueError("duplicate or empty tool call ID")
    if not text.strip() and not calls:
        raise ProviderError(
            "Response contains no supported text or tool call"
            if opaque
            else "Provider returned an empty response",
            category="unsupported_output" if opaque else "empty_response",
            usage=usage,
        )
    return ModelReply(
        text=text, calls=calls, usage=usage or {}, raw=raw, provider_model=data.get("model", "")
    )


def _refusal(usage):
    raise ProviderError("Provider explicitly refused the response", category="refusal", usage=usage)


def _text(content):
    if isinstance(content, str):
        return content
    return "\n".join(block.get("text", "") for block in content or [] if isinstance(block, dict))


def _chat_messages(messages):
    result, images = [], []
    for item in messages:
        kind = item.get("type")
        if kind == "function_call_output":
            output = item.get("output", "")
            result.append(
                {"role": "tool", "tool_call_id": item["call_id"], "content": _text(output)}
            )
            if isinstance(output, list):
                images.extend(
                    {"type": "image_url", "image_url": {"url": block["image_url"]}}
                    for block in output
                    if block.get("type") == "input_image"
                )
        elif kind == "function_call":
            call = {
                "id": item["call_id"],
                "type": "function",
                "function": {
                    "name": item["name"],
                    "arguments": item["arguments"],
                },
            }
            if result and result[-1].get("role") == "assistant":
                result[-1].setdefault("tool_calls", []).append(call)
            else:
                result.append({"role": "assistant", "content": None, "tool_calls": [call]})
        elif kind != "reasoning":
            message = {
                key: value
                for key, value in item.items()
                if key
                in {
                    "role",
                    "content",
                    "tool_calls",
                    "tool_call_id",
                    "reasoning_content",
                    "reasoning",
                }
            }
            if isinstance(message.get("content"), list):
                message["content"] = _text(message["content"])
            result.append(message)
    if images:
        result.append({"role": "user", "content": images})
    return result


def _anthropic_messages(messages):
    system, result = [], []
    for item in messages:
        if item.get("role") == "system":
            system.append(_text(item.get("content", "")))
            continue
        kind = item.get("type")
        if kind == "function_call_output":
            output = item.get("output", "")
            content = output
            if isinstance(output, list):
                content = []
                for block in output:
                    if block.get("type") == "input_image":
                        media, data = block["image_url"].split(";base64,", 1)
                        content.append(
                            {
                                "type": "image",
                                "source": {
                                    "type": "base64",
                                    "media_type": media.removeprefix("data:"),
                                    "data": data,
                                },
                            }
                        )
                    else:
                        content.append({"type": "text", "text": block.get("text", "")})
            role, blocks = (
                "user",
                [{"type": "tool_result", "tool_use_id": item["call_id"], "content": content}],
            )
        elif kind == "function_call":
            role, blocks = (
                "assistant",
                [
                    {
                        "type": "tool_use",
                        "id": item["call_id"],
                        "name": item["name"],
                        "input": json.loads(item["arguments"]),
                    }
                ],
            )
        elif kind == "reasoning":
            continue  # Responses reasoning is opaque and cannot be translated across providers.
        else:
            role = item.get("role", "assistant")
            content = item.get("content", "")
            blocks = [{"type": "text", "text": content}] if isinstance(content, str) else content
        if result and result[-1]["role"] == role:
            result[-1]["content"].extend(blocks)
        else:
            result.append({"role": role, "content": list(blocks)})

"""Explicit configuration. Repository text can never change runtime permissions."""

from __future__ import annotations

import os
import tomllib
from pathlib import Path
from typing import Annotated, Literal
from urllib.parse import urlsplit

from pydantic import ConfigDict, Field, PrivateAttr, SecretStr, model_validator

from .schema import Record

# Verified official limits; unknown model aliases deliberately use the small fallback.
# https://developers.openai.com/api/docs/models/gpt-5.6-luna (2026-09-16)
MODEL_CONTEXT_LIMITS = {
    "gpt-5.6-luna": {"window": 1_050_000, "input": 922_000, "output": 128_000},
}


class ExecRule(Record):
    prefix: list[str] = Field(min_length=1)
    decision: Literal["allow", "ask", "deny"]
    reason: str = Field(min_length=1)
    match: list[list[str]] = Field(default_factory=list)
    not_match: list[list[str]] = Field(default_factory=list)

    @model_validator(mode="after")
    def examples_match(self):
        for args in self.match:
            if args[: len(self.prefix)] != self.prefix:
                raise ValueError("rule match example does not match its prefix")
        for args in self.not_match:
            if args[: len(self.prefix)] == self.prefix:
                raise ValueError("rule not_match example matches its prefix")
        return self


class ModelProfile(Record):
    """Provider coordinates and budgets; credentials are environment references only."""

    model_config = ConfigDict(hide_input_in_errors=True)
    provider: str = Field(min_length=1)
    model: str = Field(min_length=1)
    protocol: Literal["responses", "chat", "anthropic"]
    base_url: str
    auth: Literal["required", "none"] = "required"
    api_key_env: str | None = Field(default=None, pattern=r"^[A-Za-z_][A-Za-z0-9_]*$")
    context_tokens: int = Field(ge=1024)
    output_tokens: int = Field(ge=128)
    stream: bool = False

    @model_validator(mode="after")
    def valid_profile(self):
        url = urlsplit(self.base_url)
        if (
            url.scheme not in {"https", "http"}
            or not url.hostname
            or url.username is not None
            or url.password is not None
            or url.query
            or url.fragment
        ):
            raise ValueError(
                "base_url must be an HTTP(S) endpoint without credentials, query or fragment"
            )
        if self.auth == "required" and not self.api_key_env:
            raise ValueError("auth=required needs api_key_env")
        if self.auth == "none" and self.api_key_env:
            raise ValueError("auth=none cannot specify api_key_env")
        # Use the same budget and protocol checks as an effective configuration.
        Settings(
            model=self.model,
            protocol=self.protocol,
            context_tokens=self.context_tokens,
            output_tokens=self.output_tokens,
            stream=self.stream,
        )
        return self

    def settings_values(self, credentials: dict[str, SecretStr]) -> dict:
        secret = SecretStr("")
        if self.auth == "required":
            secret = credentials.get(
                self.api_key_env, SecretStr(os.environ.get(self.api_key_env, ""))
            )
            if not secret.get_secret_value():
                raise ValueError(
                    f"missing profile credential environment variable: {self.api_key_env}"
                )
        return {**self.model_dump(exclude={"api_key_env"}), "api_key": secret}


class Settings(Record):
    model_config = ConfigDict(hide_input_in_errors=True)
    provider: str = "openai"
    profile: str | None = None
    profiles: dict[
        Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$")], ModelProfile
    ] = Field(default_factory=dict, exclude=True, repr=False)
    _profile_credentials: dict[str, SecretStr] = PrivateAttr(default_factory=dict)
    protocol: Literal["responses", "chat", "anthropic"] = "responses"
    model: str = "gpt-5.6-luna"
    base_url: str = "https://api.openai.com/v1"
    api_key: SecretStr = Field(default_factory=lambda: SecretStr(""))
    auth: Literal["required", "none"] = "required"
    stream: bool = False
    request_timeout: float = Field(default=90, gt=0, le=300)
    context_tokens: int | None = Field(
        default=None,
        ge=1024,
        description="Total token budget including output reserve; omit for the model default.",
    )
    output_tokens: int | None = Field(default=None, ge=128)
    approval: Literal["ask", "auto", "never"] = "ask"
    sandbox: Literal["required", "best_effort", "off"] = "required"
    network: bool = False
    read_only: bool = False
    write_scope: list[str] | None = None
    rules: list[ExecRule] = Field(default_factory=list)
    max_recovery: int = Field(default=1, ge=0, le=5)
    max_final_revisions: int = Field(default=2, ge=0, le=5)
    completion: Literal["off", "warn", "soft", "strict"] = "strict"
    memory_enabled: bool = False
    memory_evolution: bool = False
    auto_dream: bool = False
    tool_profile: Literal["core", "all"] = "core"
    max_workers: int = Field(default=0, ge=0, le=4)
    read_parallelism: int = Field(default=1, ge=1, le=8)
    reuse_environment: bool = False

    @model_validator(mode="after")
    def valid_budget(self):
        if self.reuse_environment and self.sandbox != "required":
            raise ValueError("reuse_environment requires sandbox=required")
        if self.stream and self.protocol != "responses":
            raise ValueError("stream currently supports only the responses protocol")
        output = self.effective_output_tokens
        if self.effective_context_tokens <= output + 256:
            raise ValueError("context_tokens must reserve output_tokens plus input space")
        if limits := MODEL_CONTEXT_LIMITS.get(self.model):
            if output > limits["output"]:
                raise ValueError("output_tokens exceeds the model output limit")
            if (
                self.effective_context_tokens > limits["window"]
                or self.effective_context_tokens - output > limits["input"]
            ):
                raise ValueError("context_tokens exceeds the model input/window limit")
        return self

    def select_profile(self, alias: str) -> Settings:
        """Resolve and validate a new selection without changing this configuration."""
        if alias not in self.profiles:
            raise ValueError(f"unknown model profile: {alias}")
        profile = self.profiles[alias]
        selected = Settings.model_validate(
            {
                **self.model_dump(),
                **profile.settings_values(self._profile_credentials),
                "profile": alias,
                "profiles": self.profiles,
            }
        )
        selected._profile_credentials = self._profile_credentials.copy()
        return selected

    @property
    def effective_context_tokens(self) -> int:
        """Resolve on access so changing a model never retains another model's auto budget."""
        if self.context_tokens is not None:
            return self.context_tokens
        limits = MODEL_CONTEXT_LIMITS.get(self.model)
        if limits is None:
            return 24000
        output = self.effective_output_tokens
        input_limit = min(limits["input"], limits["window"] - output)
        # Local token estimates can differ from the provider's count.
        return input_limit * 95 // 100 + output

    @property
    def effective_output_tokens(self) -> int:
        if self.output_tokens is not None:
            return self.output_tokens
        limits = MODEL_CONTEXT_LIMITS.get(self.model)
        if self.context_tokens is not None:
            return min(32768, self.context_tokens // 4, limits["output"] if limits else 32768)
        return min(32768, limits["output"]) if limits else 2048

    @property
    def output_budget_source(self) -> str:
        if self.output_tokens is not None:
            return "explicit"
        if self.context_tokens is not None:
            return "context_budget"
        return "model_profile" if self.model in MODEL_CONTEXT_LIMITS else "fallback"

    @property
    def context_budget_source(self) -> str:
        if self.context_tokens is not None:
            return "explicit"
        return "model_profile" if self.model in MODEL_CONTEXT_LIMITS else "fallback"

    def identity(self) -> dict:
        """Checkpoints bind to effective boundaries, not credentials."""
        identity = self.model_dump(mode="json", exclude={"api_key", "base_url"})
        identity["context_tokens"] = self.effective_context_tokens
        identity["output_tokens"] = self.effective_output_tokens
        return identity


def read_env(path: Path) -> dict[str, str]:
    """Read literal KEY=value, without executing shell or expanding variables."""
    values = {}
    if path.exists():
        for line in path.read_text().splitlines():
            if "=" not in line or line.lstrip().startswith("#"):
                continue
            key, value = line.split("=", 1)
            values[key.strip()] = value.strip().strip("\"'")
    return values


def load_settings(
    env_file: Path | None = None,
    config_file: Path | None = None,
    *,
    profile: str | None = None,
    **overrides,
) -> Settings:
    values = tomllib.loads(config_file.read_text()) if config_file else {}
    env = {**(read_env(env_file) if env_file else {}), **os.environ}
    configured_profile = values.pop("profile", None)
    alias = profile if profile is not None else configured_profile
    if alias is not None and not isinstance(alias, str):
        raise ValueError("profile must be a model profile name")
    if not isinstance(values.get("profiles", {}), dict):
        raise ValueError("profiles must be a TOML table")
    profiles = {
        name: ModelProfile.model_validate(item) for name, item in values.get("profiles", {}).items()
    }
    credentials = {
        item.api_key_env: SecretStr(env[item.api_key_env])
        for item in profiles.values()
        if item.api_key_env and item.api_key_env in env
    }
    if alias is None:
        for name in ("protocol", "model", "base_url", "api_key"):
            if env.get(f"ASTER_{name.upper()}"):
                values[name] = env[f"ASTER_{name.upper()}"]
    else:
        if alias not in profiles:
            raise ValueError(f"unknown model profile: {alias}")
        values.update(profiles[alias].settings_values(credentials))
        values["profile"] = alias
    values["profiles"] = profiles
    values.update({k: v for k, v in overrides.items() if v is not None})
    result = Settings.model_validate(values)
    result._profile_credentials = credentials
    return result

"""Small, bounded workers with narrower permissions and turn-boundary steering."""

from __future__ import annotations

import asyncio
import uuid
from dataclasses import dataclass
from pathlib import PurePosixPath
from typing import TYPE_CHECKING

from .config import Settings
from .provider import ModelClient
from .schema import TaskSpec

if TYPE_CHECKING:
    from .runtime import Runtime


def _within(path: str, directory: str) -> bool:
    return path == directory or path.startswith(directory.rstrip("/") + "/")


def _scope(requested: list[str], parent: list[str] | None) -> list[str]:
    """Intersect scopes, accepting only ordinary workspace-relative paths."""
    normalized = []
    for value in requested:
        path = PurePosixPath(value)
        if not value or path.is_absolute() or ".." in path.parts or str(path) == ".":
            raise ValueError("invalid_write_scope")
        normalized.append(str(path))
    if parent is None:
        return sorted(set(normalized))
    return sorted(
        {
            child if _within(child, allowed) else allowed
            for child in normalized
            for allowed in parent
            if _within(child, allowed) or _within(allowed, child)
        }
    )


@dataclass
class Worker:
    worker_id: str
    task: str
    mode: str
    runtime: Runtime
    future: asyncio.Task
    inbox: list[str]


class WorkerManager:
    def __init__(self, runtime: Runtime):
        self.parent = runtime
        self.workers: dict[str, Worker] = {}

    async def start(self, task: str, mode: str = "explore", write_scope: list[str] | None = None):
        if self.parent.state is None or self.parent.state.terminal:
            return {"status": "blocked", "reason": "run_terminal"}
        active = [worker for worker in self.workers.values() if not worker.future.done()]
        if len(active) >= self.parent.settings.max_workers:
            return {"status": "blocked", "reason": "worker_limit"}
        if not task.strip() or mode not in {"explore", "worker"}:
            return {"status": "blocked", "reason": "invalid_worker_request"}
        try:
            scope = _scope(write_scope or [], self.parent.settings.write_scope)
        except ValueError as exc:
            return {"status": "blocked", "reason": str(exc)}
        read_only = (
            self.parent.settings.read_only or self.parent.state.mode == "plan" or mode == "explore"
        )
        if not read_only and any(
            _within(a, b) or _within(b, a)
            for worker in active
            if not worker.runtime.settings.read_only
            for a in scope
            for b in worker.runtime.settings.write_scope or []
        ):
            return {"status": "blocked", "reason": "worker_scope_busy"}
        settings = Settings.model_validate(
            {
                **self.parent.settings.model_dump(),
                "read_only": read_only,
                "write_scope": [] if read_only else scope,
                "max_workers": 0,
                # Workers have their own working memory. The parent owns durable promotion.
                "memory_enabled": False,
                "memory_evolution": False,
                "auto_dream": False,
            }
        )
        from .runtime import Runtime

        model = (
            ModelClient(settings) if type(self.parent.model) is ModelClient else self.parent.model
        )
        runtime = Runtime(
            self.parent.workspace.root,
            settings,
            model=model,
            approval_callback=self.parent.approval_callback,
            question_callback=self.parent.question_callback,
            hooks=self.parent.hooks,
        )
        runtime.start(TaskSpec(prompt=task, max_steps=12, max_turns=12))
        runtime.state.parent_run_id = self.parent.state.run_id
        runtime.checkpoint()
        worker_id = uuid.uuid4().hex[:12]
        inbox: list[str] = []
        future = asyncio.create_task(self._run(runtime, inbox), name=f"aster-worker-{worker_id}")
        self.workers[worker_id] = Worker(worker_id, task, mode, runtime, future, inbox)
        self.parent.evidence.emit(
            self.parent.state.run_id,
            "worker_started",
            worker_id=worker_id,
            child_run_id=runtime.state.run_id,
            task=task,
            mode=mode,
            write_scope=settings.write_scope,
        )
        return {"status": "running", "worker_id": worker_id, "mode": mode}

    async def _run(self, runtime: Runtime, inbox: list[str]):
        try:
            while not runtime.state.terminal:
                if runtime.state.step >= runtime.state.task.max_steps:
                    runtime.finish("step_limit")
                    break
                for message in inbox:
                    runtime.add_message("user", message, important=True)
                    runtime.evidence.emit(
                        runtime.state.run_id, "worker_message_delivered", text=message
                    )
                inbox.clear()
                await runtime.turn()
            return runtime.state
        except asyncio.CancelledError:
            if not runtime.state.terminal:
                runtime.abort("worker_cancelled")
            raise
        except Exception:
            if not runtime.state.terminal:
                runtime.finish("worker_error", failed=True)
            raise
        finally:
            await runtime.workers.close()
            runtime.sandbox.close()

    async def status(self, worker_id: str):
        worker = self.workers.get(worker_id)
        if not worker:
            return {"status": "missing", "worker_id": worker_id}
        state = worker.runtime.state
        if worker.future.cancelled():
            return {
                "status": "cancelled",
                "worker_id": worker_id,
                "changed_paths": state.changed_paths,
            }
        if worker.future.done():
            try:
                result = worker.future.result()
                return {
                    "status": result.phase,
                    "worker_id": worker_id,
                    "stop_reason": result.stop_reason,
                    "answer": result.final,
                    "steps": result.step,
                    "changed_paths": result.changed_paths,
                }
            except Exception as exc:
                return {
                    "status": "failed",
                    "worker_id": worker_id,
                    "error": type(exc).__name__,
                    "changed_paths": state.changed_paths,
                }
        return {
            "status": state.phase,
            "worker_id": worker_id,
            "steps": state.step,
            "changed_paths": state.changed_paths,
        }

    async def message(self, worker_id: str, message: str):
        worker = self.workers.get(worker_id)
        reason = (
            "worker_missing"
            if not worker
            else "worker_finished"
            if worker.future.done() or worker.runtime.state.terminal
            else "worker_inbox_full"
            if len(worker.inbox) >= 8
            else "invalid_worker_message"
            if not message.strip() or len(message) > 8192
            else ""
        )
        if reason:
            return {"status": "blocked", "worker_id": worker_id, "reason": reason}
        worker.inbox.append(message)
        return {"status": "queued", "worker_id": worker_id}

    async def stop(self, worker_id: str):
        worker = self.workers.get(worker_id)
        if not worker:
            return {"status": "missing", "worker_id": worker_id}
        if worker.future.done():
            return await self.status(worker_id)
        worker.runtime.abort("worker_cancelled")
        if not worker.future.cancelling():
            worker.future.cancel()
        await asyncio.gather(worker.future, return_exceptions=True)
        # A coroutine cancelled before its first turn has not entered its finally block.
        if not worker.runtime.state.terminal:
            worker.runtime.abort("worker_cancelled")
        return {"status": "cancelled", "worker_id": worker_id}

    async def close(self):
        await asyncio.gather(*(self.stop(worker_id) for worker_id in self.workers))

    def cancel(self):
        """Synchronous stop request; close() still awaits subprocess cleanup."""
        for worker in self.workers.values():
            if not worker.future.done():
                if not worker.future.cancelling():
                    worker.future.cancel()
                worker.runtime.abort("worker_cancelled")

